/* @lc app=leetcode id=3505 lang=kotlin */ class Solution { fun upd(c: IntArray, s: LongArray, i0: Int, d: Int, v: Long) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < c.size }.forEach { c.set(it, c[it] + d).also { _ -> s.set(it, s[it] + d * v) } } fun qc(c: IntArray, i0: Int): Int = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { c[it] } fun qs(s: LongArray, i0: Int): Long = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { s[it] } fun kth(c: IntArray, k: Int): Int = generateSequence(Integer.highestOneBit(c.size - 1)) { it / 2 }.takeWhile { it >= 1 }.fold(0 to k) { (pos, rem), step -> if (pos + step < c.size && c[pos + step] < rem) (pos + step) to (rem - c[pos + step]) else pos to rem }.first + 1 fun minOperations(nums: IntArray, x: Int, k: Int): Long = nums.toSet().sorted().let { vals -> IntArray(vals.size + 1).let { c -> LongArray(vals.size + 1).let { s -> nums.take(x).forEach { upd(c, s, vals.binarySearch(it) + 1, 1, it.toLong()) }.let { LongArray(1).let { tot -> tot.set(0, nums.take(x).sumOf { it.toLong() }).let { (0..nums.size - x).map { st -> (if (st > 0) upd(c, s, vals.binarySearch(nums[st - 1]) + 1, -1, nums[st - 1].toLong()).also { upd(c, s, vals.binarySearch(nums[st + x - 1]) + 1, 1, nums[st + x - 1].toLong()) }.also { tot[0] += nums[st + x - 1].toLong() - nums[st - 1] } else Unit).let { kth(c, (x + 1) / 2).let { mi -> vals[mi - 1].toLong().let { med -> qc(c, mi).let { cl -> qs(s, mi).let { sl -> med * cl - sl + (tot[0] - sl) - med * (x - cl) } } } } } } } }.let { cost -> (1..k).fold(LongArray(nums.size + 1)) { prev, _ -> LongArray(nums.size + 1) { 1_000_000_000_000_000_000L }.also { cur -> (1..nums.size).forEach { i -> cur[i] = minOf(cur[i - 1], if (i >= x) prev[i - x] + cost[i - x] else 1_000_000_000_000_000_000L) } } }.last() } } } } } }